import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, loadTestFile, unzipInputArray } from '../test-utils'
import { XMLParser } from 'fast-xml-parser'

describe('log-user-name-subflow: Round-Trip Test', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    /**
     * Round-Trip Test: log-user-name-subflow
     *
     * XML Source: sys_hub_flow_430d459ef6a1407fbf3e6fe38fefe8d9.xml
     * Fluent Source: subflow-definition-examples.now.ts (logUserNameSubflow)
     *
     * Subflow Name: Log user name test subflow
     * Description: Simple subflow with inputs, outputs, assignSubflowOutputs, and log action
     *
     * This test validates:
     * - XML → Fluent transformation generates correct TypeScript code
     * - Fluent → XML transformation preserves all subflow data
     * - Round-trip maintains data integrity
     *
     * Subflow Structure:
     * - Type: Subflow
     * - Inputs: user_name (StringColumn)
     * - Outputs: successful (BooleanColumn), empDetails (ReferenceColumn)
     * - Flow Logic: assignSubflowOutputs with successful: true
     * - Action: log with datapill reference to params
     *
     * Features: Subflow inputs/outputs, assignSubflowOutputs, log action with datapill
     */
    test('log-user-name-subflow: Round-trip transformation', async () => {
        const xmlFileName = 'sys_hub_flow_430d459ef6a1407fbf3e6fe38fefe8d9.xml'
        const project = ctx.createProject()

        // ============================================================================
        // Step 1: XML → Fluent Transformation
        // ============================================================================
        const xmlContent = loadTestFile(xmlFileName, 'example-unit-tests/xml')
        const { changedFiles } = await project.transform({
            path: xmlFileName,
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        const fluentContent = changedFiles[0].getContent()
        const fluentFileName = changedFiles[0].getName()

        // Validate imports
        expect(fluentContent).toContain('import {')
        expect(fluentContent).toContain('Subflow')
        expect(fluentContent).toContain('action')
        expect(fluentContent).toContain('wfa')

        // Validate subflow definition
        expect(fluentContent).toContain('Subflow(')
        expect(fluentContent).toContain("name: 'Log user name test subflow'")
        expect(fluentContent).toContain("runAs: 'user'")

        // Validate inputs
        expect(fluentContent).toContain('inputs:')
        expect(fluentContent).toContain('user_name: StringColumn(')
        expect(fluentContent).toContain("label: 'User Name'")
        expect(fluentContent).toContain('maxLength: 8000')

        // Validate outputs
        expect(fluentContent).toContain('outputs:')
        expect(fluentContent).toContain('successful: BooleanColumn(')
        expect(fluentContent).toContain("label: 'Successful'")
        expect(fluentContent).toContain('empDetails: ReferenceColumn(')
        expect(fluentContent).toContain("label: 'Employee Details'")
        expect(fluentContent).toContain("referenceTable: 'sys_user'")
        expect(fluentContent).toContain('mandatory: true')

        // Validate Flow Logic: assignSubflowOutputs
        expect(fluentContent).toContain('wfa.flowLogic.assignSubflowOutputs(')
        expect(fluentContent).toContain("annotation: 'Test Subflow Outputs'")
        expect(fluentContent).toContain('params.outputs')
        expect(fluentContent).toContain('successful: true')

        // Validate Action: log
        expect(fluentContent).toContain('wfa.action(')
        expect(fluentContent).toContain('action.core.log')
        expect(fluentContent).toContain("annotation: 'Log user name'")
        expect(fluentContent).toContain("log_level: 'info'")
        expect(fluentContent).toContain("log_message: 'User name = '")

        // ============================================================================
        // Step 2: Fluent → XML Transformation
        // ============================================================================
        const tempProject = ctx.createProject()
        tempProject.addFile({ path: fluentFileName, content: fluentContent })

        const output = await tempProject.getFile(fluentFileName)?.getOutput()
        expect(output.length).toBeGreaterThan(0)

        // ============================================================================
        // Step 3: Parse and Validate Regenerated XML
        // ============================================================================
        const parser = new XMLParser({ ignoreAttributes: false })
        const mergedRecords: Record<string, any[]> = {}

        for (const file of output) {
            const parsed = parser.parse(file.content)['record_update']
            Object.entries(parsed).forEach(([table, value]) => {
                if (!mergedRecords[table]) {
                    mergedRecords[table] = []
                }
                if (Array.isArray(value)) {
                    mergedRecords[table].push(...value)
                } else if (value && typeof value === 'object') {
                    mergedRecords[table].push(value)
                }
            })
        }

        expect(mergedRecords['sys_hub_flow']).toBeDefined()

        // Validate subflow record
        const flows = mergedRecords['sys_hub_flow']
        const subflow = flows.find((f: any) => f.name === 'Log user name test subflow')
        expect(subflow).toBeDefined()
        expect(subflow.type).toBe('subflow')
        expect(subflow.generation_source).toBe('fluent')
        expect(subflow.run_as).toBe('user')

        // Validate subflow inputs
        if (mergedRecords['sys_hub_flow_input']) {
            const inputs = mergedRecords['sys_hub_flow_input'].filter((i: any) => i.model === subflow.sys_id)
            expect(inputs.length).toBe(1) // Exact count validation

            const userNameInput = inputs.find((i: any) => i.element === 'user_name')
            expect(userNameInput).toBeDefined()
            expect(userNameInput.label).toBe('User Name')
            expect(userNameInput.internal_type).toBe('string')
            expect(userNameInput.max_length).toBe(8000)
        }

        // Validate subflow outputs
        if (mergedRecords['sys_hub_flow_output']) {
            const outputs = mergedRecords['sys_hub_flow_output'].filter((o: any) => o.model === subflow.sys_id)
            expect(outputs.length).toBe(2)

            const successfulOutput = outputs.find((o: any) => o.element === 'successful')
            expect(successfulOutput).toBeDefined()
            expect(successfulOutput.label).toBe('Successful')
            expect(successfulOutput.internal_type).toBe('boolean')

            const empDetailsOutput = outputs.find((o: any) => o.element === 'empDetails')
            expect(empDetailsOutput).toBeDefined()
            expect(empDetailsOutput.label).toBe('Employee Details')
            expect(empDetailsOutput.internal_type).toBe('reference')
            // Reference table is stored in the 'reference' field, not 'reference_table'
            expect(empDetailsOutput.reference).toBe('sys_user')
            expect(empDetailsOutput.mandatory).toBe(true)
        }

        // Validate Flow Logic: assignSubflowOutputs
        if (mergedRecords['sys_hub_flow_logic_instance_v2']) {
            const flowLogicInstances = mergedRecords['sys_hub_flow_logic_instance_v2']
            const assignOutputs = flowLogicInstances.find(
                (fl: any) => fl.flow === subflow.sys_id && fl.comment?.includes('Test Subflow Outputs')
            )
            expect(assignOutputs).toBeDefined()
            expect(assignOutputs.logic_definition).toBeDefined()

            // Decompress and validate assignSubflowOutputs values
            const assignOutputsValues = unzipInputArray(assignOutputs.values) as any
            const assignOutputsVar = (name: string) =>
                assignOutputsValues.outputsToAssign.find((v: any) => v.name === name)?.value

            // Validate successful output assignment
            expect(assignOutputsVar('successful')).toBe('true')
        }

        // Validate Action: log
        if (mergedRecords['sys_hub_action_instance_v2']) {
            const actionInstances = mergedRecords['sys_hub_action_instance_v2']
            const logAction = actionInstances.find(
                (a: any) => a.flow === subflow.sys_id && a.comment?.includes('Log user name')
            )
            expect(logAction).toBeDefined()
            expect(logAction.action_type).toBeDefined()

            // Decompress and validate log action values
            const logValues = unzipInputArray(logAction.values)
            const logVar = (name: string) => findInput(logValues, name)?.value

            expect(logVar('log_level')).toBe('info')
            const logMessage = logVar('log_message')
            expect(logMessage).toBeDefined()
            expect(logMessage).toBe('User name = ')
        }
    })
})
